CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,payload BYTEA NOT NULL);
 CREATE TABLE IF NOT EXISTS datasets(id TEXT PRIMARY KEY,payload BYTEA NOT NULL);
 CREATE TABLE IF NOT EXISTS experiments(id TEXT PRIMARY KEY,status TEXT NOT NULL,updated_at TEXT NOT NULL,payload BYTEA NOT NULL);
 CREATE INDEX IF NOT EXISTS experiments_status ON experiments(status,updated_at);
 CREATE TABLE IF NOT EXISTS plan_versions(experiment_id TEXT NOT NULL REFERENCES experiments(id) ON DELETE CASCADE,version INTEGER NOT NULL,payload BYTEA NOT NULL,PRIMARY KEY(experiment_id,version));
 CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,experiment_id TEXT NOT NULL REFERENCES experiments(id) ON DELETE CASCADE,kind TEXT NOT NULL,message TEXT NOT NULL,created_at TEXT NOT NULL);
 CREATE INDEX IF NOT EXISTS events_experiment ON events(experiment_id,id);
 CREATE TABLE IF NOT EXISTS artifacts(experiment_id TEXT NOT NULL REFERENCES experiments(id) ON DELETE CASCADE,name TEXT NOT NULL,payload BYTEA NOT NULL,PRIMARY KEY(experiment_id,name));
